function decode(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const CARLITO_BYTES = {
  regular: () => decode(CARLITO_REGULAR_B64),
  bold: () => decode(CARLITO_BOLD_B64),
  italic: () => decode(CARLITO_ITALIC_B64),
  boldItalic: () => decode(CARLITO_BOLDITALIC_B64),
} as const;

export type CarlitoFace = keyof typeof CARLITO_BYTES;
